import React, { useEffect, useState, useMemo, useCallback } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";
import "./Shop.css";

const API_BASE_URL = "http://localhost:5009";
const SEARCH_DEBOUNCE_MS = 300;

// Five spine colors so the grid reads like a shelf of varied books,
// assigned deterministically per book id (no randomness on re-render).
const SPINE_COLORS = ["spine-brass", "spine-red", "spine-sage", "spine-slate", "spine-clay"];

function extractUserId(decoded) {
  const raw = decoded?.userId || decoded?.id || decoded?._id || decoded?.sub || "";
  return String(raw).trim() || null;
}

function spineClassFor(id) {
  const str = String(id || "");
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
  return SPINE_COLORS[hash % SPINE_COLORS.length];
}

function catalogNumberFor(id) {
  const str = String(id || "").replace(/[^a-zA-Z0-9]/g, "");
  return str.slice(-4).toUpperCase().padStart(4, "0");
}

function useDebouncedValue(value, delayMs) {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(timer);
  }, [value, delayMs]);

  return debounced;
}

function Shop({ onBuy, purchasedItems = {} }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const debouncedSearchTerm = useDebouncedValue(searchTerm, SEARCH_DEBOUNCE_MS);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    try {
      const decoded = jwtDecode(token);
      setCurrentUserId(extractUserId(decoded));
    } catch (err) {
      setCurrentUserId(null);
    }
  }, []);

  useEffect(() => {
    const controller = new AbortController();

    setLoading(true);
    setError(null);

    fetch(`${API_BASE_URL}/books`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`Request failed with status ${res.status}`);
        return res.json();
      })
      .then((data) => setItems(Array.isArray(data) ? data : []))
      .catch((err) => {
        if (err.name !== "AbortError") setError("Couldn't reach the stacks.");
      })
      .finally(() => setLoading(false));

    return () => controller.abort();
  }, [reloadKey]);

  const filteredItems = useMemo(() => {
    if (!items.length) return [];

    const currentId = String(currentUserId || "").trim();
    const search = debouncedSearchTerm.toLowerCase().trim();

    return items.filter((item) => {
      if (!item) return false;

      const sellerId = String(item.sellerId?._id || "").trim();
      const isNotMine = !currentId || sellerId !== currentId;

      const title = (item.title || "").toLowerCase().trim();
      const matchesSearch = search === "" || title.includes(search);

      return isNotMine && matchesSearch;
    });
  }, [items, currentUserId, debouncedSearchTerm]);

  const handleRetry = useCallback(() => setReloadKey((k) => k + 1), []);

  return (
    <>
      <Navbar />

      <div className="Body shop-page">
        <div className="catalog-lookup-wrap">
          <label className="catalog-lookup-label" htmlFor="shop-search">
            Find a Book
          </label>
          <div className="catalog-lookup">
            <input
              id="shop-search"
              type="text"
              placeholder="Search the stacks…"
              aria-label="Search for books"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="catalog-lookup-input"
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm("")}
                aria-label="Clear search"
                className="catalog-lookup-clear"
              >
                ×
              </button>
            )}
          </div>
        </div>

        <div className="shop-grid">
          {loading ? (
            <div className="shop-status">
              <p className="shop-status-text">Pulling books off the shelf…</p>
            </div>
          ) : error ? (
            <div className="shop-status">
              <p className="shop-status-text">{error}</p>
              <button className="shop-retry-btn" onClick={handleRetry}>
                Try again
              </button>
            </div>
          ) : filteredItems.length === 0 ? (
            <div className="shop-status">
              <p className="shop-status-text">
                {searchTerm
                  ? `No matches for "${searchTerm}" in the stacks.`
                  : "The shelf's empty for now."}
              </p>
            </div>
          ) : (
            filteredItems.map((item) => {
              const itemId = String(item._id || item.id);
              const isPurchased = !!purchasedItems[itemId];

              return (
                <div key={itemId} className={`catalog-card ${spineClassFor(itemId)}`}>
                  <span className="catalog-card-number">No. {catalogNumberFor(itemId)}</span>
                  <div className="catalog-card-body">
                    <Card {...item} />
                    <button
                      onClick={() => !isPurchased && onBuy(item)}
                      disabled={isPurchased}
                      aria-label={
                        isPurchased
                          ? "Already added to cart"
                          : `Add ${item.title || "item"} to cart`
                      }
                      className={`catalog-buy-btn ${isPurchased ? "catalog-buy-btn--disabled" : ""}`}
                    >
                      {isPurchased ? "Added to Cart" : "Add to Cart"}
                    </button>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      <Footer />
    </>
  );
}

export default Shop;
